<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('forms.view');$formId=max(0,(int)($_GET['form_id']??$_POST['form_id']??0));$pageTitle='Leads recibidos';
if($_SERVER['REQUEST_METHOD']==='POST'&&has_permission('forms.manage')){verify_csrf();$submissionId=(int)($_POST['submission_id']??0);$s=db()->prepare('SELECT ls.*,lf.name form_name FROM lead_submissions ls JOIN lead_forms lf ON lf.id=ls.form_id WHERE ls.id=?');$s->execute([$submissionId]);$lead=$s->fetch();if($lead&&!$lead['converted_contact_id']){$pdo=db();$pdo->beginTransaction();try{$parts=preg_split('/\s+/',trim((string)($lead['name']?:'Lead')));$first=array_shift($parts)?:'Lead';$last=implode(' ',$parts);$pdo->prepare("INSERT INTO contacts(first_name,last_name,email,phone,language,status,source,owner_user_id,notes) VALUES (?,?,?,?,?,'lead',?,?,?)")->execute([$first,$last,$lead['email'],$lead['phone'],'es','Formulario: '.$lead['form_name'],(int)$_SESSION['user_id'],'País: '.($lead['country']?:'')]);$contactId=(int)$pdo->lastInsertId();$stageId=(int)$pdo->query("SELECT id FROM pipeline_stages WHERE is_active=1 ORDER BY sort_order,id LIMIT 1")->fetchColumn();$dealId=null;if($stageId){$pdo->prepare("INSERT INTO deals(title,contact_id,owner_user_id,stage_id,probability,status,source,created_by) VALUES (?,?,?,?,10,'open','Formulario web',?)")->execute(['Lead · '.($lead['name']?:$lead['email']?:'Nuevo contacto'),$contactId,(int)$_SESSION['user_id'],$stageId,(int)$_SESSION['user_id']]);$dealId=(int)$pdo->lastInsertId();}$pdo->prepare('UPDATE lead_submissions SET converted_contact_id=?,converted_deal_id=? WHERE id=?')->execute([$contactId,$dealId,$submissionId]);$pdo->commit();flash('success','Lead convertido en contacto y negocio.');}catch(Throwable$e){$pdo->rollBack();flash('error',$e->getMessage());}}redirect('lead_submissions.php'.($formId?'?form_id='.$formId:''));}
$where=$formId?' WHERE ls.form_id=?':'';$s=db()->prepare("SELECT ls.*,lf.name form_name,lf.title form_title FROM lead_submissions ls JOIN lead_forms lf ON lf.id=ls.form_id{$where} ORDER BY ls.created_at DESC");$s->execute($formId?[$formId]:[]);$rows=$s->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Respuestas de formularios</h2><span class="table-sub">Convierte un lead en contacto y oportunidad comercial con un clic.</span></div><a class="btn btn-light" href="lead_forms.php">Formularios</a></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">Todavía no se han recibido leads.</div><?php else:?><table class="data-table"><thead><tr><th>Persona</th><th>Formulario</th><th>Contacto</th><th>País</th><th>Fecha</th><th>Conversión</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><strong><?=e($r['name']?:'Sin nombre')?></strong><span class="table-sub"><?=e(crm_strimwidth((string)$r['data_json'],90))?></span></td><td><?=e($r['form_name'])?></td><td><?=e($r['email']?:'—')?><span class="table-sub"><?=e($r['phone']?:'')?></span></td><td><?=e($r['country']?:'—')?></td><td><?=e((new DateTimeImmutable($r['created_at']))->format('d/m/Y H:i'))?></td><td><?php if($r['converted_contact_id']):?><a class="badge badge-green" href="contact_view.php?id=<?=(int)$r['converted_contact_id']?>">Convertido</a><?php elseif(has_permission('forms.manage')):?><form method="post"><?=csrf_field()?><input type="hidden" name="form_id" value="<?=$formId?>"><input type="hidden" name="submission_id" value="<?=(int)$r['id']?>"><button class="btn btn-secondary btn-small">Convertir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
